/// Provides administrative access to an IceGrid deployment.
public protocol Admin: Ice.Dispatcher {
    /// Adds an application to IceGrid.
    ///
    /// - Parameters:
    ///   - descriptor: The application descriptor.
    ///   - current: The Current object for the dispatch.
    ///
    /// - Throws: AccessDeniedException Thrown when the session doesn't hold the exclusive lock or when another
    ///     session is holding the lock. DeploymentException Thrown when the application deployment failed.
    func addApplication(descriptor: sending ApplicationDescriptor, current: Ice.Current) async throws

    /// Synchronizes a deployed application. This operation replaces the current descriptor with a new descriptor.
    ///
    /// - Parameters:
    ///   - descriptor: The new application descriptor.
    ///   - current: The Current object for the dispatch.
    ///
    /// - Throws: AccessDeniedException Thrown when the session doesn't hold the exclusive lock or when another
    ///     session is holding the lock. ApplicationNotExistException Thrown when the application doesn't exist. DeploymentException Thrown when the application deployment failed.
    func syncApplication(descriptor: sending ApplicationDescriptor, current: Ice.Current) async throws

    /// Updates a deployed application.
    ///
    /// - Parameters:
    ///   - descriptor: The update descriptor.
    ///   - current: The Current object for the dispatch.
    ///
    /// - Throws: AccessDeniedException Thrown when the session doesn't hold the exclusive lock or when another
    ///     session is holding the lock. ApplicationNotExistException Thrown when the application doesn't exist. DeploymentException Thrown when the application deployment failed.
    func updateApplication(descriptor: sending ApplicationUpdateDescriptor, current: Ice.Current) async throws

    /// Synchronizes a deployed application. This operation replaces the current descriptor with a new descriptor
    /// only if no server restarts are necessary for the update of the application. If some servers need to be
    /// restarted, the synchronization is rejected with a DeploymentException.
    ///
    /// - Parameters:
    ///   - descriptor: The application descriptor.
    ///   - current: The Current object for the dispatch.
    ///
    /// - Throws: AccessDeniedException Thrown when the session doesn't hold the exclusive lock or when another
    ///     session is holding the lock. ApplicationNotExistException Thrown when the application doesn't exist. DeploymentException Thrown when the application deployment failed.
    func syncApplicationWithoutRestart(descriptor: sending ApplicationDescriptor, current: Ice.Current) async throws

    /// Updates a deployed application. This operation succeeds only when no server restarts are necessary for the
    /// update of the application. If some servers need to be restarted, the synchronization is rejected with a
    /// DeploymentException.
    ///
    /// - Parameters:
    ///   - descriptor: The update descriptor.
    ///   - current: The Current object for the dispatch.
    ///
    /// - Throws: AccessDeniedException Thrown when the session doesn't hold the exclusive lock or when another
    ///     session is holding the lock. ApplicationNotExistException Thrown when the application doesn't exist. DeploymentException Thrown when the application deployment failed.
    func updateApplicationWithoutRestart(descriptor: sending ApplicationUpdateDescriptor, current: Ice.Current) async throws

    /// Removes an application from IceGrid.
    ///
    /// - Parameters:
    ///   - name: The application name.
    ///   - current: The Current object for the dispatch.
    ///
    /// - Throws: AccessDeniedException Thrown when the session doesn't hold the exclusive lock or when another
    ///     session is holding the lock. ApplicationNotExistException Thrown when the application doesn't exist. DeploymentException Thrown when the application deployment failed.
    func removeApplication(name: Swift.String, current: Ice.Current) async throws

    /// Instantiates a server template.
    ///
    /// - Parameters:
    ///   - application: The application name.
    ///   - node: The name of the node where the server will be deployed.
    ///   - desc: The descriptor of the server instance to deploy.
    ///   - current: The Current object for the dispatch.
    ///
    /// - Throws: AccessDeniedException Thrown when the session doesn't hold the exclusive lock or when another
    ///     session is holding the lock. ApplicationNotExistException Thrown when the application doesn't exist. DeploymentException Thrown when the application deployment failed.
    func instantiateServer(application: Swift.String, node: Swift.String, desc: ServerInstanceDescriptor, current: Ice.Current) async throws

    /// Gets an application descriptor.
    ///
    /// - Parameters:
    ///   - name: The application name.
    ///   - current: The Current object for the dispatch.
    ///
    /// - Returns: The application descriptor.
    ///
    /// - Throws:
    ///   - ApplicationNotExistException Thrown when the application doesn't exist.
    func getApplicationInfo(name: Swift.String, current: Ice.Current) async throws -> ApplicationInfo

    /// Gets the default application descriptor.
    ///
    /// - Parameter current: The Current object for the dispatch.
    ///
    /// - Returns: The default application descriptor.
    ///
    /// - Throws:
    ///   - DeploymentException Thrown when the default application descriptor is invalid or unreachable.
    func getDefaultApplicationDescriptor(current: Ice.Current) async throws -> ApplicationDescriptor

    /// Gets all the IceGrid applications currently registered.
    ///
    /// - Parameter current: The Current object for the dispatch.
    ///
    /// - Returns: The application names.
    func getAllApplicationNames(current: Ice.Current) async throws -> Ice.StringSeq

    /// Gets information about a server.
    ///
    /// - Parameters:
    ///   - id: The server ID.
    ///   - current: The Current object for the dispatch.
    ///
    /// - Returns: The server information.
    ///
    /// - Throws:
    ///   - ServerNotExistException Thrown when the server doesn't exist.
    func getServerInfo(id: Swift.String, current: Ice.Current) async throws -> ServerInfo

    /// Gets the state of a server.
    ///
    /// - Parameters:
    ///   - id: The server ID.
    ///   - current: The Current object for the dispatch.
    ///
    /// - Returns: The server state.
    ///
    /// - Throws: DeploymentException Thrown when the deployment of the server failed. NodeUnreachableException Thrown when the node is unreachable. ServerNotExistException Thrown when the server doesn't exist.
    func getServerState(id: Swift.String, current: Ice.Current) async throws -> ServerState

    /// Gets the system process ID of a server. The process ID is operating system dependent.
    ///
    /// - Parameters:
    ///   - id: The server ID.
    ///   - current: The Current object for the dispatch.
    ///
    /// - Returns: The process ID.
    ///
    /// - Throws: DeploymentException Thrown when the deployment of the server failed. NodeUnreachableException Thrown when the node is unreachable. ServerNotExistException Thrown when the server doesn't exist.
    func getServerPid(id: Swift.String, current: Ice.Current) async throws -> Swift.Int32

    /// Gets the category for server admin objects. You can manufacture a server admin proxy from the admin proxy by
    /// changing its identity: use the server ID as name and the returned category as category.
    ///
    /// - Parameter current: The Current object for the dispatch.
    ///
    /// - Returns: The category for server admin objects.
    func getServerAdminCategory(current: Ice.Current) async throws -> Swift.String

    /// Gets a proxy to the admin object of a server.
    ///
    /// - Parameters:
    ///   - id: The server ID.
    ///   - current: The Current object for the dispatch.
    ///
    /// - Returns: A proxy to the admin object of the server. This proxy is never null.
    ///
    /// - Throws: DeploymentException Thrown when the deployment of the server failed. NodeUnreachableException Thrown when the node is unreachable. ServerNotExistException Thrown when the server doesn't exist.
    func getServerAdmin(id: Swift.String, current: Ice.Current) async throws -> Ice.ObjectPrx?

    /// Enables or disables a server. A disabled server can't be started on demand or administratively. The enable
    /// state of the server is not persistent: if the node is shut down and restarted, the server will be enabled by
    /// default.
    ///
    /// - Parameters:
    ///   - id: The server ID.
    ///   - enabled: `true` to enable the server, `false` to disable it.
    ///   - current: The Current object for the dispatch.
    ///
    /// - Throws: DeploymentException Thrown when the deployment of the server failed. NodeUnreachableException Thrown when the node is unreachable. ServerNotExistException Thrown when the server doesn't exist.
    func enableServer(id: Swift.String, enabled: Swift.Bool, current: Ice.Current) async throws

    /// Checks if the server is enabled or disabled.
    ///
    /// - Parameters:
    ///   - id: The server ID.
    ///   - current: The Current object for the dispatch.
    ///
    /// - Returns: `true` if the server is enabled, `false` otherwise.
    ///
    /// - Throws: DeploymentException Thrown when the deployment of the server failed. NodeUnreachableException Thrown when the node is unreachable. ServerNotExistException Thrown when the server doesn't exist.
    func isServerEnabled(id: Swift.String, current: Ice.Current) async throws -> Swift.Bool

    /// Starts a server and waits for its activation.
    ///
    /// - Parameters:
    ///   - id: The server id.
    ///   - current: The Current object for the dispatch.
    ///
    /// - Throws: DeploymentException Thrown when the deployment of the server failed. NodeUnreachableException Thrown when the node is unreachable. ServerNotExistException Thrown when the server doesn't exist. ServerStartException Thrown when the server startup failed.
    func startServer(id: Swift.String, current: Ice.Current) async throws

    /// Stops a server.
    ///
    /// - Parameters:
    ///   - id: The server ID.
    ///   - current: The Current object for the dispatch.
    ///
    /// - Throws: DeploymentException Thrown when the deployment of the server failed. NodeUnreachableException Thrown when the node is unreachable. ServerNotExistException Thrown when the server doesn't exist. ServerStopException Thrown when the server stop failed.
    func stopServer(id: Swift.String, current: Ice.Current) async throws

    /// Sends a signal to a server.
    ///
    /// - Parameters:
    ///   - id: The server ID.
    ///   - signal: The signal, for example SIGTERM or 15.
    ///   - current: The Current object for the dispatch.
    ///
    /// - Throws: BadSignalException Thrown when the signal is not recognized by the target server. DeploymentException Thrown when the deployment of the server failed. NodeUnreachableException Thrown when the node is unreachable. ServerNotExistException Thrown when the server doesn't exist.
    func sendSignal(id: Swift.String, signal: Swift.String, current: Ice.Current) async throws

    /// Gets the IDs of all the servers registered with IceGrid.
    ///
    /// - Parameter current: The Current object for the dispatch.
    ///
    /// - Returns: The server IDs.
    func getAllServerIds(current: Ice.Current) async throws -> Ice.StringSeq

    /// Gets adapter information for the replica group or adapter with the given ID.
    ///
    /// - Parameters:
    ///   - id: The adapter or replica group ID.
    ///   - current: The Current object for the dispatch.
    ///
    /// - Returns: A sequence of AdapterInfo. If @p id refers to an adapter, this sequence contains a single element.
    /// If @p id refers to a replica group, this sequence contains adapter information for each member of the
    /// replica group.
    ///
    /// - Throws:
    ///   - AdapterNotExistException Thrown when the adapter or replica group doesn't exist.
    func getAdapterInfo(id: Swift.String, current: Ice.Current) async throws -> AdapterInfoSeq

    /// Removes the adapter with the given ID.
    ///
    /// - Parameters:
    ///   - id: The adapter ID.
    ///   - current: The Current object for the dispatch.
    ///
    /// - Throws: AdapterNotExistException Thrown when the adapter doesn't exist. DeploymentException Thrown when the application deployment failed.
    func removeAdapter(id: Swift.String, current: Ice.Current) async throws

    /// Gets the IDs of all adapters registered with IceGrid.
    ///
    /// - Parameter current: The Current object for the dispatch.
    ///
    /// - Returns: The adapter IDs.
    func getAllAdapterIds(current: Ice.Current) async throws -> Ice.StringSeq

    /// Adds an object to the object registry. IceGrid gets the object type by calling `ice_id` on @p obj. The
    /// object must be reachable.
    ///
    /// - Parameters:
    ///   - obj: A proxy to the object. This proxy is never null.
    ///   - current: The Current object for the dispatch.
    ///
    /// - Throws: DeploymentException Thrown when the object can't be added. ObjectExistsException Thrown when the object is already registered.
    func addObject(obj: Ice.ObjectPrx?, current: Ice.Current) async throws

    /// Updates an object in the object registry. Only objects added with this interface can be updated with this
    /// operation. Objects added with deployment descriptors should be updated with the deployment mechanism.
    ///
    /// - Parameters:
    ///   - obj: A proxy to the object. This proxy is never null.
    ///   - current: The Current object for the dispatch.
    ///
    /// - Throws: DeploymentException Thrown when the object can't be updated. ObjectNotRegisteredException Thrown when the object isn't registered with the registry.
    func updateObject(obj: Ice.ObjectPrx?, current: Ice.Current) async throws

    /// Adds an object to the object registry and explicitly specifies its type.
    ///
    /// - Parameters:
    ///   - obj: The object to be added to the registry. The proxy is never null.
    ///   - type: The type name.
    ///   - current: The Current object for the dispatch.
    ///
    /// - Throws: DeploymentException Thrown when the application deployment failed. ObjectExistsException Thrown when the object is already registered.
    func addObjectWithType(obj: Ice.ObjectPrx?, type: Swift.String, current: Ice.Current) async throws

    /// Removes an object from the object registry. Only objects added with this interface can be removed with this
    /// operation. Objects added with deployment descriptors should be removed with the deployment mechanism.
    ///
    /// - Parameters:
    ///   - id: The identity of the object to remove.
    ///   - current: The Current object for the dispatch.
    ///
    /// - Throws: DeploymentException Thrown when the object can't be removed. ObjectNotRegisteredException Thrown when the object isn't registered with the registry.
    func removeObject(id: Ice.Identity, current: Ice.Current) async throws

    /// Gets the object info for the object.
    ///
    /// - Parameters:
    ///   - id: The identity of the object.
    ///   - current: The Current object for the dispatch.
    ///
    /// - Returns: The object info.
    ///
    /// - Throws:
    ///   - ObjectNotRegisteredException Thrown when the object isn't registered with the registry.
    func getObjectInfo(id: Ice.Identity, current: Ice.Current) async throws -> ObjectInfo

    /// Gets the object info of all the registered objects with a given type.
    ///
    /// - Parameters:
    ///   - type: The type name.
    ///   - current: The Current object for the dispatch.
    ///
    /// - Returns: The object infos.
    func getObjectInfosByType(type: Swift.String, current: Ice.Current) async throws -> ObjectInfoSeq

    /// Gets the object info of all the registered objects whose stringified identities match the given expression.
    ///
    /// - Parameters:
    ///   - expr: The expression to match against the stringified identities of registered objects. The expression
    /// may contain a trailing wildcard (`*`) character.
    ///   - current: The Current object for the dispatch.
    ///
    /// - Returns: All the object infos with a stringified identity matching the given expression.
    func getAllObjectInfos(expr: Swift.String, current: Ice.Current) async throws -> ObjectInfoSeq

    /// Pings an IceGrid node to see if it is active.
    ///
    /// - Parameters:
    ///   - name: The node name.
    ///   - current: The Current object for the dispatch.
    ///
    /// - Returns: `true` if the node ping succeeded, `false` otherwise.
    ///
    /// - Throws:
    ///   - NodeNotExistException Thrown when the node doesn't exist.
    func pingNode(name: Swift.String, current: Ice.Current) async throws -> Swift.Bool

    /// Gets the load averages of a node.
    ///
    /// - Parameters:
    ///   - name: The node name.
    ///   - current: The Current object for the dispatch.
    ///
    /// - Returns: The node load information.
    ///
    /// - Throws: NodeNotExistException Thrown when the node doesn't exist. NodeUnreachableException Thrown when the node is unreachable.
    func getNodeLoad(name: Swift.String, current: Ice.Current) async throws -> LoadInfo

    /// Gets the node information of a node.
    ///
    /// - Parameters:
    ///   - name: The node name.
    ///   - current: The Current object for the dispatch.
    ///
    /// - Returns: The node information.
    ///
    /// - Throws: NodeNotExistException Thrown when the node doesn't exist. NodeUnreachableException Thrown when the node is unreachable.
    func getNodeInfo(name: Swift.String, current: Ice.Current) async throws -> NodeInfo

    /// Gets a proxy to the admin object of an IceGrid node.
    ///
    /// - Parameters:
    ///   - name: The IceGrid node name.
    ///   - current: The Current object for the dispatch.
    ///
    /// - Returns: A proxy to the IceGrid node's admin object. This proxy is never null.
    ///
    /// - Throws: NodeNotExistException Thrown when the node doesn't exist. NodeUnreachableException Thrown when the node is unreachable.
    func getNodeAdmin(name: Swift.String, current: Ice.Current) async throws -> Ice.ObjectPrx?

    /// Gets the number of physical processor sockets in the computer where an IceGrid node is deployed.
    /// Note that this operation returns 1 on operating systems where this can't be automatically determined and
    /// where the `IceGrid.Node.ProcessorSocketCount` property for the node is not set.
    ///
    /// - Parameters:
    ///   - name: The node name.
    ///   - current: The Current object for the dispatch.
    ///
    /// - Returns: The number of processor sockets or 1 if the number of sockets can't be determined.
    ///
    /// - Throws: NodeNotExistException Thrown when the node doesn't exist. NodeUnreachableException Thrown when the node is unreachable.
    func getNodeProcessorSocketCount(name: Swift.String, current: Ice.Current) async throws -> Swift.Int32

    /// Shuts down an IceGrid node.
    ///
    /// - Parameters:
    ///   - name: The node name.
    ///   - current: The Current object for the dispatch.
    ///
    /// - Throws: NodeNotExistException Thrown when the node doesn't exist. NodeUnreachableException Thrown when the node is unreachable.
    func shutdownNode(name: Swift.String, current: Ice.Current) async throws

    /// Get the hostname of a node.
    ///
    /// - Parameters:
    ///   - name: The node name.
    ///   - current: The Current object for the dispatch.
    ///
    /// - Returns: The node hostname.
    ///
    /// - Throws: NodeNotExistException Thrown when the node doesn't exist. NodeUnreachableException Thrown when the node is unreachable.
    func getNodeHostname(name: Swift.String, current: Ice.Current) async throws -> Swift.String

    /// Gets the names of all IceGrid nodes currently registered.
    ///
    /// - Parameter current: The Current object for the dispatch.
    ///
    /// - Returns: The node names.
    func getAllNodeNames(current: Ice.Current) async throws -> Ice.StringSeq

    /// Pings an IceGrid registry to see if it is active.
    ///
    /// - Parameters:
    ///   - name: The registry name.
    ///   - current: The Current object for the dispatch.
    ///
    /// - Returns: `true` if the registry ping succeeded, `false` otherwise.
    ///
    /// - Throws:
    ///   - RegistryNotExistException Thrown when the registry doesn't exist.
    func pingRegistry(name: Swift.String, current: Ice.Current) async throws -> Swift.Bool

    /// Gets the registry information of an IceGrid registry.
    ///
    /// - Parameters:
    ///   - name: The registry name.
    ///   - current: The Current object for the dispatch.
    ///
    /// - Returns: The registry information.
    ///
    /// - Throws: RegistryNotExistException Thrown when the registry doesn't exist. RegistryUnreachableException Thrown when the registry is unreachable.
    func getRegistryInfo(name: Swift.String, current: Ice.Current) async throws -> RegistryInfo

    /// Gets a proxy to the admin object of an IceGrid registry.
    ///
    /// - Parameters:
    ///   - name: The registry name.
    ///   - current: The Current object for the dispatch.
    ///
    /// - Returns: A proxy to the admin object of an IceGrid registry. This proxy is never null.
    ///
    /// - Throws:
    ///   - RegistryNotExistException Thrown when the registry doesn't exist.
    func getRegistryAdmin(name: Swift.String, current: Ice.Current) async throws -> Ice.ObjectPrx?

    /// Shuts down an IceGrid registry.
    ///
    /// - Parameters:
    ///   - name: The registry name.
    ///   - current: The Current object for the dispatch.
    ///
    /// - Throws: RegistryNotExistException Thrown when the registry doesn't exist. RegistryUnreachableException Thrown when the registry is unreachable.
    func shutdownRegistry(name: Swift.String, current: Ice.Current) async throws

    /// Gets the names of all the IceGrid registries currently registered.
    ///
    /// - Parameter current: The Current object for the dispatch.
    ///
    /// - Returns: The registry names.
    func getAllRegistryNames(current: Ice.Current) async throws -> Ice.StringSeq

    /// Shuts down the IceGrid registry.
    ///
    /// - Parameter current: The Current object for the dispatch.
    func shutdown(current: Ice.Current) async throws
}

/// Iterates over an IceGrid log file.
public protocol FileIterator: Ice.Dispatcher {
    /// Read lines from the log file.
    ///
    /// - Parameters:
    ///   - size: Specifies the maximum number of bytes to be received. The server will ensure that the returned
    /// message doesn't exceed the given size.
    ///   - current: The Current object for the dispatch.
    ///
    /// - Returns:
    ///   - returnValue: `true` if EOF is encountered.
    ///   - lines: The lines read from the file. If there was nothing to read from the file since the last call to
    /// read, an empty sequence is returned. The last line of the sequence is always incomplete (and therefore no
    /// newline character should be added when writing the last line to the to the output device).
    ///
    /// - Throws:
    ///   - FileNotAvailableException Thrown when the implementation failed to read from the file.
    func read(size: Swift.Int32, current: Ice.Current) async throws -> (returnValue: Swift.Bool, lines: Ice.StringSeq)

    /// Destroys the iterator.
    ///
    /// - Parameter current: The Current object for the dispatch.
    func destroy(current: Ice.Current) async throws
}

/// Monitors changes to the state of the registries.
public protocol RegistryObserver: Ice.Dispatcher {
    /// Provides the initial state of the registries to the observer.
    ///
    /// - Parameters:
    ///   - registries: The current state of the registries.
    ///   - current: The Current object for the dispatch.
    func registryInit(registries: RegistryInfoSeq, current: Ice.Current) async throws

    /// Notifies the observer that a registry replica came up.
    ///
    /// - Parameters:
    ///   - registryReplica: The registry state.
    ///   - current: The Current object for the dispatch.
    func registryUp(registryReplica: RegistryInfo, current: Ice.Current) async throws

    /// Notifies the observer that a registry replica went down.
    ///
    /// - Parameters:
    ///   - name: The registry name.
    ///   - current: The Current object for the dispatch.
    func registryDown(name: Swift.String, current: Ice.Current) async throws
}

/// Monitors changes to the state of the nodes.
public protocol NodeObserver: Ice.Dispatcher {
    /// Provides the initial state of the nodes to the observer.
    ///
    /// - Parameters:
    ///   - nodes: The current state of the nodes.
    ///   - current: The Current object for the dispatch.
    func nodeInit(nodes: NodeDynamicInfoSeq, current: Ice.Current) async throws

    /// Notifies the observer that a node came up.
    ///
    /// - Parameters:
    ///   - node: The node state.
    ///   - current: The Current object for the dispatch.
    func nodeUp(node: NodeDynamicInfo, current: Ice.Current) async throws

    /// Notifies the observer that a node went down.
    ///
    /// - Parameters:
    ///   - name: The node name.
    ///   - current: The Current object for the dispatch.
    func nodeDown(name: Swift.String, current: Ice.Current) async throws

    /// Notifies the observer that the state of a server changed.
    ///
    /// - Parameters:
    ///   - node: The node hosting the server.
    ///   - updatedInfo: The new server state.
    ///   - current: The Current object for the dispatch.
    func updateServer(node: Swift.String, updatedInfo: ServerDynamicInfo, current: Ice.Current) async throws

    /// Notifies the observer that the state of an object adapter changed.
    ///
    /// - Parameters:
    ///   - node: The node hosting the adapter.
    ///   - updatedInfo: The new adapter state.
    ///   - current: The Current object for the dispatch.
    func updateAdapter(node: Swift.String, updatedInfo: AdapterDynamicInfo, current: Ice.Current) async throws
}

/// Monitors applications.
public protocol ApplicationObserver: Ice.Dispatcher {
    /// Provides the initial application infos to the observer.
    ///
    /// - Parameters:
    ///   - serial: The current serial number of the registry database. This serial number allows observers to
    /// make sure that their internal state is synchronized with the registry.
    ///   - applications: The applications currently registered with the registry.
    ///   - current: The Current object for the dispatch.
    func applicationInit(serial: Swift.Int32, applications: sending ApplicationInfoSeq, current: Ice.Current) async throws

    /// Notifies the observer that an application was added.
    ///
    /// - Parameters:
    ///   - serial: The new serial number of the registry database.
    ///   - desc: The descriptor of the new application.
    ///   - current: The Current object for the dispatch.
    func applicationAdded(serial: Swift.Int32, desc: sending ApplicationInfo, current: Ice.Current) async throws

    /// Notifies the observer that an application was removed.
    ///
    /// - Parameters:
    ///   - serial: The new serial number of the registry database.
    ///   - name: The name of the application that was removed.
    ///   - current: The Current object for the dispatch.
    func applicationRemoved(serial: Swift.Int32, name: Swift.String, current: Ice.Current) async throws

    /// Notifies the observer that an application was updated.
    ///
    /// - Parameters:
    ///   - serial: The new serial number of the registry database.
    ///   - desc: The descriptor of the update.
    ///   - current: The Current object for the dispatch.
    func applicationUpdated(serial: Swift.Int32, desc: sending ApplicationUpdateInfo, current: Ice.Current) async throws
}

/// Monitors dynamically-registered object adapters.
public protocol AdapterObserver: Ice.Dispatcher {
    /// Provides the initial list of dynamically registered adapters to the observer.
    ///
    /// - Parameters:
    ///   - adpts: The adapters that were dynamically registered with the registry.
    ///   - current: The Current object for the dispatch.
    func adapterInit(adpts: AdapterInfoSeq, current: Ice.Current) async throws

    /// Notifies the observer that a dynamically-registered adapter was added.
    ///
    /// - Parameters:
    ///   - info: The details of the new adapter.
    ///   - current: The Current object for the dispatch.
    func adapterAdded(info: AdapterInfo, current: Ice.Current) async throws

    /// - Parameters:
    ///   - info: The details of the updated adapter.
    ///   - current: The Current object for the dispatch.
    func adapterUpdated(info: AdapterInfo, current: Ice.Current) async throws

    /// Notifies the observer that a dynamically-registered adapter was removed.
    ///
    /// - Parameters:
    ///   - id: The ID of the removed adapter.
    ///   - current: The Current object for the dispatch.
    func adapterRemoved(id: Swift.String, current: Ice.Current) async throws
}

/// Monitors well-known objects that are added, updated or removed using ``AdminPrx``.
public protocol ObjectObserver: Ice.Dispatcher {
    /// Provides the initial list of well-known objects to the observer.
    ///
    /// - Parameters:
    ///   - objects: The well-known objects registered using ``AdminPrx``.
    ///   - current: The Current object for the dispatch.
    func objectInit(objects: ObjectInfoSeq, current: Ice.Current) async throws

    /// Notifies the observer that a well-known object was added.
    ///
    /// - Parameters:
    ///   - info: The details of the new object.
    ///   - current: The Current object for the dispatch.
    func objectAdded(info: ObjectInfo, current: Ice.Current) async throws

    /// Notifies the observer that a well-known object was updated.
    ///
    /// - Parameters:
    ///   - info: The details of the updated object.
    ///   - current: The Current object for the dispatch.
    func objectUpdated(info: ObjectInfo, current: Ice.Current) async throws

    /// Notifies the observer that a well-known object was removed.
    ///
    /// - Parameters:
    ///   - id: The identity of the removed object.
    ///   - current: The Current object for the dispatch.
    func objectRemoved(id: Ice.Identity, current: Ice.Current) async throws
}

/// Represents an administrative session between an admin tool and an IceGrid registry.
public protocol AdminSession: Glacier2.Session {
    /// Keeps the session alive.
    ///
    /// - Parameter current: The Current object for the dispatch.
    func keepAlive(current: Ice.Current) async throws

    /// Gets a proxy to the IceGrid admin object. The admin object returned by this operation can only be accessed
    /// by the session.
    ///
    /// - Parameter current: The Current object for the dispatch.
    ///
    /// - Returns: A proxy to the IceGrid admin object. This proxy is never null.
    func getAdmin(current: Ice.Current) async throws -> AdminPrx?

    /// Gets a "template" proxy for admin callback objects. An Admin client uses this proxy to set the category of
    /// its callback objects, and the published endpoints of the object adapter hosting the admin callback objects.
    ///
    /// - Parameter current: The Current object for the dispatch.
    ///
    /// - Returns: A template proxy. The returned proxy is null when the Admin session was established using Glacier2.
    func getAdminCallbackTemplate(current: Ice.Current) async throws -> Ice.ObjectPrx?

    /// Sets the observer proxies that receive notifications when the state of the registry or nodes changes.
    ///
    /// - Parameters:
    ///   - registryObs: The registry observer.
    ///   - nodeObs: The node observer.
    ///   - appObs: The application observer.
    ///   - adptObs: The adapter observer.
    ///   - objObs: The object observer.
    ///   - current: The Current object for the dispatch.
    ///
    /// - Throws:
    ///   - ObserverAlreadyRegisteredException Thrown when an observer is already registered with this registry.
    func setObservers(registryObs: RegistryObserverPrx?, nodeObs: NodeObserverPrx?, appObs: ApplicationObserverPrx?, adptObs: AdapterObserverPrx?, objObs: ObjectObserverPrx?, current: Ice.Current) async throws

    /// Sets the observer identities that receive notifications when the state of the registry or nodes changes.
    /// This operation should be used by clients that are using a bidirectional connection to communicate with the
    /// session.
    ///
    /// - Parameters:
    ///   - registryObs: The registry observer identity.
    ///   - nodeObs: The node observer identity.
    ///   - appObs: The application observer.
    ///   - adptObs: The adapter observer.
    ///   - objObs: The object observer.
    ///   - current: The Current object for the dispatch.
    ///
    /// - Throws:
    ///   - ObserverAlreadyRegisteredException Thrown when an observer is already registered with this registry.
    func setObserversByIdentity(registryObs: Ice.Identity, nodeObs: Ice.Identity, appObs: Ice.Identity, adptObs: Ice.Identity, objObs: Ice.Identity, current: Ice.Current) async throws

    /// Acquires an exclusive lock to start updating the registry applications.
    ///
    /// - Parameter current: The Current object for the dispatch.
    ///
    /// - Returns: The current serial.
    ///
    /// - Throws:
    ///   - AccessDeniedException Thrown when the exclusive lock can't be acquired. This might happen if the
    ///     lock is currently acquired by another session.
    func startUpdate(current: Ice.Current) async throws -> Swift.Int32

    /// Finishes updating the registry and releases the exclusive lock.
    ///
    /// - Parameter current: The Current object for the dispatch.
    ///
    /// - Throws:
    ///   - AccessDeniedException Thrown when the session doesn't hold the exclusive lock.
    func finishUpdate(current: Ice.Current) async throws

    /// Gets the name of the registry replica hosting this session.
    ///
    /// - Parameter current: The Current object for the dispatch.
    ///
    /// - Returns: The replica name of the registry.
    func getReplicaName(current: Ice.Current) async throws -> Swift.String

    /// Opens a server log file for reading.
    ///
    /// - Parameters:
    ///   - id: The server ID.
    ///   - path: The path of the log file. A log file can be opened only if it's declared in the server or
    /// service deployment descriptor.
    ///   - count: Specifies where to start reading the file. If negative, the file is read from the beginning.
    /// Otherwise, the file is read from the last @p count lines.
    ///   - current: The Current object for the dispatch.
    ///
    /// - Returns: An iterator to read the file. This proxy is never null.
    ///
    /// - Throws: DeploymentException Thrown when the server couldn't be deployed on the node. FileNotAvailableException Thrown when the file can't be read. NodeUnreachableException Thrown when the node is unreachable. ServerNotExistException Thrown when the server doesn't exist.
    func openServerLog(id: Swift.String, path: Swift.String, count: Swift.Int32, current: Ice.Current) async throws -> FileIteratorPrx?

    /// Opens a server stderr file for reading.
    ///
    /// - Parameters:
    ///   - id: The server ID.
    ///   - count: Specifies where to start reading the file. If negative, the file is read from the beginning.
    /// Otherwise, the file is read from the last @p count lines.
    ///   - current: The Current object for the dispatch.
    ///
    /// - Returns: An iterator to read the file. This proxy is never null.
    ///
    /// - Throws: DeploymentException Thrown when the server couldn't be deployed on the node. FileNotAvailableException Thrown when the file can't be read. NodeUnreachableException Thrown when the node is unreachable. ServerNotExistException Thrown when the server doesn't exist.
    func openServerStdErr(id: Swift.String, count: Swift.Int32, current: Ice.Current) async throws -> FileIteratorPrx?

    /// Opens a server stdout file for reading.
    ///
    /// - Parameters:
    ///   - id: The server id.
    ///   - count: Specifies where to start reading the file. If negative, the file is read from the beginning.
    /// Otherwise, the file is read from the last @p count lines.
    ///   - current: The Current object for the dispatch.
    ///
    /// - Returns: An iterator to read the file. This proxy is never null.
    ///
    /// - Throws: DeploymentException Thrown when the server couldn't be deployed on the node. FileNotAvailableException Thrown when the file can't be read. NodeUnreachableException Thrown when the node is unreachable. ServerNotExistException Thrown when the server doesn't exist.
    func openServerStdOut(id: Swift.String, count: Swift.Int32, current: Ice.Current) async throws -> FileIteratorPrx?

    /// Opens a node stderr file for reading.
    ///
    /// - Parameters:
    ///   - name: The node name.
    ///   - count: Specifies where to start reading the file. If negative, the file is read from the beginning.
    /// Otherwise, the file is read from the last @p count lines.
    ///   - current: The Current object for the dispatch.
    ///
    /// - Returns: An iterator to read the file. This proxy is never null.
    ///
    /// - Throws: FileNotAvailableException Thrown when the file can't be read. NodeNotExistException Thrown when the node doesn't exist. NodeUnreachableException Thrown when the node is unreachable.
    func openNodeStdErr(name: Swift.String, count: Swift.Int32, current: Ice.Current) async throws -> FileIteratorPrx?

    /// Opens a node stdout file for reading.
    ///
    /// - Parameters:
    ///   - name: The node name.
    ///   - count: Specifies where to start reading the file. If negative, the file is read from the beginning.
    /// Otherwise, the file is read from the last @p count lines.
    ///   - current: The Current object for the dispatch.
    ///
    /// - Returns: An iterator to read the file. This proxy is never null.
    ///
    /// - Throws: FileNotAvailableException Thrown when the file can't be read. NodeNotExistException Thrown when the node doesn't exist. NodeUnreachableException Thrown when the node is unreachable.
    func openNodeStdOut(name: Swift.String, count: Swift.Int32, current: Ice.Current) async throws -> FileIteratorPrx?

    /// Opens a registry stderr file for reading.
    ///
    /// - Parameters:
    ///   - name: The registry name.
    ///   - count: Specifies where to start reading the file. If negative, the file is read from the beginning.
    /// Otherwise, the file is read from the last @p count lines.
    ///   - current: The Current object for the dispatch.
    ///
    /// - Returns: An iterator to read the file. This proxy is never null.
    ///
    /// - Throws: FileNotAvailableException Thrown when the file can't be read. RegistryNotExistException Thrown when the registry doesn't exist. RegistryUnreachableException Thrown when the registry is unreachable.
    func openRegistryStdErr(name: Swift.String, count: Swift.Int32, current: Ice.Current) async throws -> FileIteratorPrx?

    /// Opens a registry stdout file for reading.
    ///
    /// - Parameters:
    ///   - name: The registry name.
    ///   - count: Specifies where to start reading the file. If negative, the file is read from the beginning.
    /// Otherwise, the file is read from the last @p count lines.
    ///   - current: The Current object for the dispatch.
    ///
    /// - Returns: An iterator to read the file. This proxy is never null.
    ///
    /// - Throws: FileNotAvailableException Thrown when the file can't be read. RegistryNotExistException Thrown when the registry doesn't exist. RegistryUnreachableException Thrown when the registry is unreachable.
    func openRegistryStdOut(name: Swift.String, count: Swift.Int32, current: Ice.Current) async throws -> FileIteratorPrx?
}

/// Provides administrative access to an IceGrid deployment.
///
/// Admin Methods:
///  - addApplication: Adds an application to IceGrid.
///  - syncApplication: Synchronizes a deployed application.
///  - updateApplication: Updates a deployed application.
///  - syncApplicationWithoutRestart: Synchronizes a deployed application.
///  - updateApplicationWithoutRestart: Updates a deployed application.
///  - removeApplication: Removes an application from IceGrid.
///  - instantiateServer: Instantiates a server template.
